function hottest(nodes){
  let best = null;
  for (const n of nodes){
    const cost = n.perLoopMs;
    if (best === null || cost > best.cost) best = { name: n.name, cost };
  }
  return best.name;
}

tasks.verify:
const nodes = [
  { name:'A', perLoopMs:0.03, loops:120000 },
  { name:'B', perLoopMs:50, loops:1 },
  { name:'C', perLoopMs:2, loops:300 }
];
const ok = hottest(nodes) === 'A';
console.log(ok ? 'PASS' : 'FAIL ' + hottest(nodes));
